    });
        }
    
    pub fn close(self: *@This()) void {
                switch (self.*) {
    .memfd => |fd| {
    self.* = .closed;
                _ = fd.close();
    },
    .fd => {
    self.* = .closed;
    },
    .pipe => {
    _ = self.pipe.close();
    },
    else => {
    
    },
    }
        }
    
    pub fn finalize(self: *@This()) void {
                switch (self.*) {
    .memfd => |fd| {
    self.* = .closed;
                _ = fd.close();
    },
    .fd => {
    self.* = .closed;
    },
    .pipe => |pipe| {
    defer {
                _ = pipe.detach();
                }
                self.* = .closed;
    },
    else => {
    
    },
    }
        }
    };
    pub const Flags = packed struct(u8) {
            is_sync: bool = false,
            killed: bool = false,
            waiting_for_onexit: bool = false,
            _: u5 = 0,
        };
    pub const SignalCode = bun.SignalCode;
    pub const StaticPipeWriter = jsc.Subprocess.NewStaticPipeWriter(ShellSubprocess);
    pub const SpawnArgs = SubprocSpawnArgs;
    pub const WatchFd = bun.FD;
};

pub const OptFD = ?bun.FD;
pub const EnvStrZ = ?[*:0]const u8;
const SelfPtr = *ShellSubprocess;
pub const Stdio = util.Stdio;
const StdioResult = (if (Environment.isWindows) bun.spawn.WindowsSpawnResult.StdioResult else OptFD);
const ShellCmd = bun.shell.Interpreter.Cmd;
const log = Output.scoped(.SHELL_SUBPROC, .visible);
pub const PipeReaderState = union(enum) {
    pending: void,
    done: []u8,
    err: ?jsc.SystemError,
};
pub const PipeReader = struct {
    reader: IOReader = undefined,
    process: ?*ShellSubprocess = null,
    event_loop: jsc.EventLoopHandle = undefined,
    state: PipeReaderState = .pending,
    stdio_result: StdioResult,
    out_type: bun.shell.subproc.ShellSubprocess.OutKind,
    captured_writer: CapturedWriter = .{},
    buffered_output: BufferedOutput = .{ .bytelist = .{} },
    ref_count: RefCount,

pub fn detach(self: *@This()) void {
            _ = log("PipeReader(0x{x}, {s}) detach()", .{ @intFromPtr(self), @tagName(self.out_type) });
            self.process = null;
            _ = self.deref();
    }

pub fn isDone(self: *@This()) bool {
            _ = log("PipeReader(0x{x}, {s}) isDone() state={s} captured_writer_done={}", .{ @intFromPtr(self), @tagName(self.out_type), @tagName(self.state), self.captured_writer.isDone(0) });
            if ((self.state == .pending)) {
                return false;
            }
            return self.captured_writer.isDone(0);
    }

pub fn onCapturedWriterDone(self: *@This()) void {
            var done_yield = self.trySignalDoneToCmd();
            _ = &done_yield;
            _ = done_yield.run();
    }

pub fn create(event_loop: jsc.EventLoopHandle, process: *ShellSubprocess, result: StdioResult, capture: ?*sh.IOWriter, out_type: bun.shell.Subprocess.OutKind) *PipeReader {
            var pipe_reader: *PipeReader = bun.new(PipeReader, .{ .ref_count = .init(), .process = process, .reader = IOReader.init(@This()), .event_loop = event_loop, .stdio_result = result, .out_type = out_type });
            _ = &pipe_reader;
            _ = log("PipeReader(0x{x}, {s}) create()", .{ @intFromPtr(pipe_reader), @tagName(pipe_reader.out_type) });
            if (capture) |cap| {
                _ = &cap;
                pipe_reader.captured_writer.writer = cap.dupeRef();
                pipe_reader.captured_writer.dead = false;
            }
            if (Environment.isWindows) {
                pipe_reader.reader.source = (switch (result) {
.buffer => .{ .pipe = pipe_reader.stdio_result.buffer },
.buffer_fd => .{ .file = bun.io.Source.openFile(pipe_reader.stdio_result.buffer_fd) },
.unavailable => @panic("Shouldn't happen."),
});
            }
            _ = pipe_reader.reader.setParent(pipe_reader);
            return pipe_reader;
    }

pub fn readAll(self: *@This()) void {
            if ((self.state == .pending)) {
                _ = self.reader.read();
            }
    }

pub fn start(self: *@This(), process: *ShellSubprocess, event_loop: jsc.EventLoopHandle) bun.sys.Maybe(void) {
            self.process = process;
            self.event_loop = event_loop;
            if (Environment.isWindows) {
                return self.reader.startWithCurrentPipe();
            }
            switch (self.reader.start(self.stdio_result.?, true)) {
.err => |e| {
return .{ .err = e };
},
.result => {
if (comptime Environment.isPosix) {
                const poll = self.reader.handle.poll;
                _ = poll.flags.insert(.socket);
                self.reader.flags.socket = true;
            }
            return .success;
},
}
    }

pub fn onReadChunk(ptr: *anyopaque, chunk: []const u8, has_more: bun.io.ReadState) bool {
            var reader: *PipeReader = @ptrCast(@alignCast(ptr));
            _ = &reader;
            _ = reader.buffered_output.append(chunk);
            _ = log("PipeReader(0x{x}, {s}) onReadChunk(chunk_len={d}, has_more={s})", .{ @intFromPtr(reader), @tagName(reader.out_type), chunk.len, @tagName(has_more) });
            _ = reader.captured_writer.doWrite(chunk);
            const should_continue = (has_more != .eof);
            if (should_continue) {
                if (bun.Environment.isPosix) {
                    _ = reader.reader.registerPoll();
                } else {
                    switch (reader.reader.startWithCurrentPipe()) {
.err => |e| {
_ = Output.panic("TODO: implement error handling in Bun Shell PipeReader.onReadChunk\n{f}", .{ e });
},
else => {

},
}
                }
            }
            return should_continue;
    }

pub fn onReaderDone(self: *@This()) void {
            _ = log("onReaderDone(0x{x}, {s})", .{ @intFromPtr(self), @tagName(self.out_type) });
            const owned = self.toOwnedSlice();
            self.state = .{ .done = owned };
            if ((!self.isDone())) {
                return;
            }
            _ = self.ref();
            defer {
            _ = self.deref();
            }
            var done_yield = self.trySignalDoneToCmd();
            _ = &done_yield;
            _ = done_yield.run();
            if (self.process) |process| {
                _ = &process;
                _ = process.onCloseIO(self.kind(process));
                _ = self.deref();
            }
    }

pub fn trySignalDoneToCmd(self: *@This()) Yield {
            if ((!self.isDone())) {
                return .suspended;
            }
            _ = log("signalDoneToCmd ({x}: {s}) isDone={}", .{ @intFromPtr(self), @tagName(self.out_type), self.isDone() });
            if (bun.Environment.allow_assert) {
                _ = assert((self.process != null));
            }
            if (self.process) |proc| {
                _ = &proc;
                const cmd = proc.cmd_parent;
                if (self.captured_writer.err) |e| {
                    _ = &e;
                    self.captured_writer.err = null;
                    if ((self.state == .done)) {
                        _ = bun.default_allocator.free(self.state.done);
                    }
                    if ((self.state != .err)) {
                        self.state = .{ .err = e };
                    } else {
                        _ = e.deref();
                    }
                }
                const e: ?jsc.SystemError = brk: {
                if ((self.state != .err)) {
                    break :brk null;
                }
                if ((self.state.err != null)) {
                    var e_ptr = (&self.state.err.?);
                    _ = &e_ptr;
                    _ = e_ptr.ref();
                    break :brk e_ptr.*;
                }
                break :brk null;
};
                return cmd.bufferedOutputClose(self.out_type, e);
            }
            return .suspended;
    }

pub fn kind(reader: *const PipeReader, process: *const ShellSubprocess) StdioKind {
            if (((process.stdout == .pipe) and (process.stdout.pipe == reader))) {
                return .stdout;
            }
            if (((process.stderr == .pipe) and (process.stderr.pipe == reader))) {
                return .stderr;
            }
            _ = @panic("We should be either stdout or stderr");
    }

pub fn takeBuffer(self: *@This()) std.array_list.Managed(u8) {
            return self.reader.takeBuffer();
    }

pub fn slice(self: *@This()) []const u8 {
            return self.buffered_output.slice();
    }

pub fn toOwnedSlice(self: *@This()) []u8 {
            if ((self.state == .done)) {
                return self.state.done;
            }
            const out = self.reader._buffer;
            self.reader._buffer.items = &.{};
            self.reader._buffer.capacity = 0;
            if (((out.capacity > 0) and (out.items.len == 0))) {
                _ = out.deinit();
                return &.{};
            }
            return out.items;
    }

pub fn updateRef(self: *@This(), add: bool) void {
            _ = self.reader.updateRef(add);
    }

pub fn watch(self: *@This()) void {
            if ((!self.reader.isDone())) {
                _ = self.reader.watch();
            }
    }

pub fn toReadableStream(self: *@This(), globalObject: *jsc.JSGlobalObject) jsc.JSValue {
            defer {
            _ = self.deinit();
            }
            switch (self.state) {
.pending => {
const stream = jsc.WebCore.ReadableStream.fromPipe(globalObject, self, (&self.reader));
            self.state = .{ .done = &.{} };
            return stream;
},
.done => |bytes| {
self.state = .{ .done = &.{} };
            return jsc.WebCore.ReadableStream.fromOwnedSlice(globalObject, bytes, 0);
},
.err => |e| {
_ = &e;
            const empty = try jsc.WebCore.ReadableStream.empty(globalObject);
            _ = jsc.WebCore.ReadableStream.cancel((&(jsc.WebCore.ReadableStream.fromJS(empty, globalObject)).?), globalObject);
            return empty;
},
}
    }

pub fn toBuffer(self: *@This(), globalThis: *jsc.JSGlobalObject) jsc.JSValue {
            switch (self.state) {
.done => |bytes| {
defer {
            self.state = .{ .done = &.{} };
            }
            return jsc.MarkedArrayBuffer.fromBytes(bytes, bun.default_allocator, .Uint8Array).toNodeBuffer(globalThis);
},
else => {
return .js_undefined;
},
}
    }

pub fn onReaderError(self: *@This(), e: bun.sys.Error) void {
            _ = log("PipeReader(0x{x}) onReaderError {f}", .{ @intFromPtr(self), e });
            if ((self.state == .done)) {
                _ = bun.default_allocator.free(self.state.done);
            }
            self.state = .{ .err = e.toSystemError() };
            _ = self.ref();
            defer {
            _ = self.deref();
            }
            var done_yield = self.trySignalDoneToCmd();
            _ = &done_yield;
            _ = done_yield.run();
            if (self.process) |process| {
                _ = &process;
                _ = process.onCloseIO(self.kind(process));
                _ = self.deref();
            }
    }

pub fn close(self: *@This()) void {
            switch (self.state) {
.pending => {
_ = self.reader.close();
},
.done => {

},
.err => {

},
}
    }

pub fn eventLoop(self: *@This()) jsc.EventLoopHandle {
            return self.event_loop;
    }

pub fn loop(self: *@This()) *bun.Async.Loop {
            if (comptime bun.Environment.isWindows) {
                return self.event_loop.loop().uv_loop;
            } else {
                return self.event_loop.loop();
            }
    }

pub fn deinit(self: *@This()) void {
            _ = log("PipeReader(0x{x}, {s}) deinit()", .{ @intFromPtr(self), @tagName(self.out_type) });
            if (comptime Environment.isPosix) {
                _ = assert((self.reader.isDone() or (self.state == .err)));
            }
            if (comptime Environment.isWindows) {
                _ = assert(((self.reader.source == null) or self.reader.source.?.isClosed()));
            }
            if ((self.state == .done)) {
                _ = bun.default_allocator.free(self.state.done);
            }
            if ((!self.captured_writer.dead)) {
                _ = self.captured_writer.deinit();
            }
            if ((self.state == .err)) {
                if (self.state.err) |e| {
                    _ = &e;
                    _ = e.deref();
                    self.state.err = null;
                }
            }
            _ = self.buffered_output.deinit();
            _ = self.reader.deinit();
            _ = bun.destroy(self);
    }
    const RefCount = bun.ptr.RefCount(@This(), "ref_count", deinit, .{});
    pub const ref = RefCount.ref;
    pub const deref = RefCount.deref;
    const BufferedOutput = SubprocBufferedOutput;
    pub const CapturedWriter = SubprocCapturedWriter;
    pub const IOReader = bun.io.BufferedReader;
    pub const Poll = IOReader;
    pub const toJS = toReadableStream;
};
